type Consent = "unknown" | "granted" | "denied";
export function mayTrack(consent: Consent, necessary: boolean) {
  if (necessary) return true;
  return consent === "granted";
}
console.assert(mayTrack("unknown", false) === false);
console.assert(mayTrack("denied", false) === false);
console.assert(mayTrack("granted", false) === true);

exercise.solution:
في الموافقة وتقليل البيانات يحافظ الحل على سلطة واحدة ويطبق تحديدًا «تحميل الأدوات غير الضرورية بعد الموافقة واحترام الرفض والسحب وفصل التخزين الضروري عن القياس الاختياري وتوثيق الغرض». يجعل يُحمّل SDK قبل اللافتة ثم ترشح mayTrack الأحداث فقط رغم أن المزوّد استلم طلبًا بالفعل قابلًا للتكرار ثم مضبوطًا ولا يُقبل إلا عندما لا تصدر unknown وdenied أي استدعاء تحليلات غير ضروري وتسمح granted به ويوقف سحب الموافقة الاستدعاءات التالية.
